import{_ as e,p as a,q as l,Y as t}from"./framework-e1bed10d.js";const i={},o=t('<h1 id="日期类" tabindex="-1"><a class="header-anchor" href="#日期类" aria-hidden="true">#</a> 日期类</h1><h2 id="date类" tabindex="-1"><a class="header-anchor" href="#date类" aria-hidden="true">#</a> Date类</h2><ol><li>new Date()：创建一个Date对象，该对象表示当前时间</li><li>new Date(long millis)：创建一个Date对象，该对象表示1970年1月1日0时0分0秒到当前时间之间所经过的毫秒数</li><li>Date.parse(String s)：将字符串s转换成Date对象，字符串s必须遵循&quot;yyyy-MM-dd HH:mm:ss&quot;的格式，否则将返回-1</li><li>Date.getTime()：返回1970年1月1日0时0分0秒到当前时间之间所经过的毫秒数</li><li>Date.toString()：返回当前时间对应的字符串，格式为&quot;EEE MMM dd HH:mm:ss zzz yyyy&quot;</li><li>Date.getYear()/Date.getFullYear()：返回当前时间对应的年份，从1900年开始计算</li><li>Date.getMonth()：返回当前时间对应的月份，从0开始计算</li><li>Date.getDate()：返回当前时间对应的日期，从1开始计算</li><li>Date.getHours()：返回当前时间对应的小时，从0开始计算</li><li>Date.getMinutes()：返回当前时间对应的分钟，从0开始计算</li><li>Date.getSeconds()：返回当前时间对应的秒钟，从0开始计算</li><li>Date.getMilliseconds()：返回当前时间对应的毫秒，从0开始计算</li><li>Date.getDay()：返回当前时间对应的星期，从0开始计算，0表示星期天，1表示星期一，以此类推</li><li>Date.setTime(long time)：设置当前时间，参数为毫秒数</li></ol><h2 id="calendar类" tabindex="-1"><a class="header-anchor" href="#calendar类" aria-hidden="true">#</a> Calendar类</h2><p>Calendar 类是一个抽象类，它提供了在特定时刻和一组 calendar fields 之间转换的方法，例如 YEAR 、 MONTH 、 DAY_OF_MONTH 、 HOUR 等，以及用于操作日历字段的方法，例如获取日期下个星期</p><p>时间可以用毫秒值表示，该值是从Epoch开始的偏移量，1970 年 1 月 1 日 00:00:00.000 GMT（公历）。</p><p>该类还提供了额外的字段和方法，用于在包外实现具体的日历系统。这些字段和方法定义为 protected 。</p><p>与其他locale敏感的类一样，Calendar提供了一个类方法getInstance ，用于获取此类型的普遍有用的对象。 Calendar的getInstance方法返回一个Calendar对象，其日历字段已用当前日期和时间初始化</p><h3 id="常用静态值" tabindex="-1"><a class="header-anchor" href="#常用静态值" aria-hidden="true">#</a> 常用静态值</h3><ol><li>YEAR：get 和 set 的字段编号表示年份</li><li>MONTH：get 和 set 的字段编号表示月份</li><li>DAY_OF_MONTH：get 和 set 的字段编号指示月份中的日期</li><li>HOUR_OF_DAY：get 和 set 的字段编号指示一天中的小时数</li><li>MINUTE：get 和 set 的字段编号表示小时内的分钟</li><li>SECOND：get 和 set 的字段编号表示分钟内的秒数</li><li>MILLISECOND：get 和 set 的字段编号表示秒内的毫秒数</li><li>WEEK_OF_MONTH：get 和 set 的字段编号表示当月的周数</li><li>WEEK_OF_YEAR：get 和 set 的字段编号表示年的周数</li><li>DAY_OF_WEEK：get 和 set 的字段编号表示星期几</li></ol><h3 id="静态方法" tabindex="-1"><a class="header-anchor" href="#静态方法" aria-hidden="true">#</a> 静态方法</h3><ol><li>static Calendar getInstance()：使用默认时区和locale获取日历</li><li>static Calendar getInstance(Locale aLocale)：获取使用默认时区和指定locale的日历</li><li>static Calendar getInstance(TimeZone zone)：获取使用指定时区和默认locale的日历</li><li>static Calendar getInstance(TimeZone zone, Locale aLocale)：获取具有指定时区和locale的日历</li></ol><h3 id="判断方法" tabindex="-1"><a class="header-anchor" href="#判断方法" aria-hidden="true">#</a> 判断方法</h3><ol><li>int compareTo(Calendar anotherCalendar)：比较两个日历对象的大小，返回一个整数，如果当前日历对象早于 anotherCalendar，则返回一个负数；如果当前日历对象晚于 anotherCalendar，则返回一个正数；如果两个日历对象相等，则返回 0</li><li>boolean after(Object when)：返回此 Calendar 是否表示指定 Object 表示的时间之后的时间。</li><li>boolean before(Object when)： 返回此 Calendar 是否表示指定 Object 表示的时间之前的时间。</li><li>boolean equals(Object obj)： 将此 Calendar 与指定的 Object 进行比较。</li></ol><h3 id="获取日历对象相关信息" tabindex="-1"><a class="header-anchor" href="#获取日历对象相关信息" aria-hidden="true">#</a> 获取日历对象相关信息</h3><ol><li>int get(int field)：返回给定日历字段的值。</li><li>String getCalendarType()：返回此 Calendar 的日历类型</li><li>int getFirstDayOfWeek()：获取一周的第一天是什么；例如，SUNDAY 在美国，MONDAY 在法国</li><li>Date getTime()：返回表示此 Calendar 的时间值的Date对象</li><li>long getTimeInMillis():以毫秒为单位返回此日历的时间</li><li>boolean isSet(int field)：确定给定的日历字段是否设置了值，包括值已由 get 方法调用触发的内部字段计算设置的情况</li><li>TimeZone getTimeZone()：获取时区</li><li>String getDisplayName(int field, int style, Locale locale)：返回给定 style 和 locale 中日历 field 值的字符串表示形式。</li><li>Map&lt;String,Integer&gt; getDisplayNames(int field, int style, Locale locale)：返回一个 Map，其中包含给定 style 和 locale 中日历 field 的所有名称及其对应的字段值</li></ol><h3 id="设置日历对象相关信息" tabindex="-1"><a class="header-anchor" href="#设置日历对象相关信息" aria-hidden="true">#</a> 设置日历对象相关信息</h3><ol><li>void set(int field, int value)：将给定的日历字段设置为给定的值</li><li>final void set(int year, int month, int date)：设置日历字段 YEAR 、 MONTH 和 DAY_OF_MONTH 的值</li><li>final void set(int year, int month, int date, int hourOfDay, int minute)：设置日历字段 YEAR、MONTH、DAY_OF_MONTH、HOUR_OF_DAY 和 MINUTE 的值</li><li>final void set(int year, int month, int date, int hourOfDay, int minute, int second)：设置字段 YEAR、MONTH、DAY_OF_MONTH、HOUR_OF_DAY、MINUTE 和 SECOND 的值。</li><li>void setFirstDayOfWeek(int value)：设置一周的第一天是什么；例如，SUNDAY 在美国，MONDAY 在法国</li><li>abstract void add(int field, int amount)：根据日历的规则向给定的日历字段添加或减去指定的时间量。</li></ol><h2 id="localdate类" tabindex="-1"><a class="header-anchor" href="#localdate类" aria-hidden="true">#</a> LocalDate类</h2><p>LocalDate 是一个不可变且线程安全的日期时间对象，表示日期，通常被视为年月日。还可以访问其他日期字段，例如一年中的某一天、星期几和一年中的一周，没有偏移量或时区等附加信息，它不能代表时间线上的一个瞬间</p><h3 id="静态变量" tabindex="-1"><a class="header-anchor" href="#静态变量" aria-hidden="true">#</a> 静态变量</h3><ol><li>static final LocalDate EPOCH：纪元年 LocalDate，&#39;1970-01-01&#39;。</li><li>static final LocalDate MAX：最大支持 LocalDate，&#39;+999999999-12-31&#39;。</li><li>static final LocalDate MIN：支持的最小值 LocalDate，&#39;-999999999-01-01&#39;</li></ol><h3 id="静态方法-1" tabindex="-1"><a class="header-anchor" href="#静态方法-1" aria-hidden="true">#</a> 静态方法</h3><ol><li>static LocalDate now()：从默认时区的系统时钟获取当前日期。</li><li>static LocalDate now(Clock clock)：从指定时钟获取当前日期。</li><li>static LocalDate now(ZoneId zone)：从指定时区的系统时钟获取当前日期</li><li>static LocalDate of(int year, int month, int dayOfMonth)：从年、月和日中获取 LocalDate 的实例。</li><li>static LocalDate of(int year, Month month, int dayOfMonth)：从年、月和日中获取 LocalDate 的实例</li><li>static LocalDate parse(CharSequence text)：从 2007-12-03 等文本字符串中获取 LocalDate 的实例</li></ol><h3 id="实例方法" tabindex="-1"><a class="header-anchor" href="#实例方法" aria-hidden="true">#</a> 实例方法</h3><ol><li>LocalDateTime atTime(int hour, int minute)：将此日期与时间结合起来创建一个 LocalDateTime 。</li><li>LocalDateTime atTime(int hour, int minute, int second)：将此日期与时间结合起来创建一个 LocalDateTime</li><li>LocalDateTime atTime(LocalTime time)：将此日期与时间结合起来创建一个 LocalDateTime</li><li>boolean isLeapYear()：根据 ISO proleptic 日历系统规则，检查年份是否为闰年</li><li>Period until(ChronoLocalDate endDateExclusive)：计算此日期和另一个日期之间的时间为 Period</li></ol><h3 id="查询方法" tabindex="-1"><a class="header-anchor" href="#查询方法" aria-hidden="true">#</a> 查询方法</h3><ol><li>int get(TemporalField field)：从此日期获取指定字段的值</li><li>int getYear()：获取年份字段</li><li>int DayOfWeek getDayOfWeek()：获取星期字段，它是一个枚举DayOfWeek</li><li>Month getMonth() 使用 Month 枚举获取月份字段</li><li>int getMonthValue()：获取从1到12的月份字段</li><li>int getDayOfMonth()：获取日期字段</li></ol><h3 id="操作方法" tabindex="-1"><a class="header-anchor" href="#操作方法" aria-hidden="true">#</a> 操作方法</h3><ol><li>LocalDate minus(long amountToSubtract, TemporalUnit unit)：返回此日期的副本，并减去指定的日期</li><li>LocalDate minus(TemporalAmount amountToSubtract) ：回此日期的副本，并减去指定的日期</li><li>LocalDate minusDays(long daysToSubtract)：返回此 LocalDate 的副本，并减去指定的天数</li><li>LocalDate minusMonths(long monthsToSubtract)：返回此 LocalDate 的副本，并减去指定的月数</li><li>LocalDate minusWeeks(long weeksToSubtract)：返回此 LocalDate 的副本，并减去指定的周数</li><li>LocalDate minusYears(long yearsToSubtract)：返回此 LocalDate 的副本，并减去指定的年数</li><li>LocalDate plus(long amountToAdd, TemporalUnit unit)：返回添加了指定数量的此日期的副本</li><li>LocalDate plus(TemporalAmount amountToAdd)：返回添加了指定数量的此日期的副本</li><li>LocalDate plusDays(long daysToAdd)：返回此 LocalDate 的副本，并添加了指定的天数</li><li>LocalDate plusMonths(long monthsToAdd)：返回此 LocalDate 的副本，并添加了指定的月数</li><li>LocalDate plusWeeks(long weeksToAdd)：返回此 LocalDate 的副本，并添加了指定的周数</li><li>LocalDate plusYears(long yearsToAdd)：返回此 LocalDate 的副本，并添加了指定的年数</li></ol><h3 id="比较方法" tabindex="-1"><a class="header-anchor" href="#比较方法" aria-hidden="true">#</a> 比较方法</h3><ol><li>int compareTo(ChronoLocalDate other)：将此日期与另一个日期进行比较</li><li>boolean equals(Object obj)：检查此日期是否等于另一个日期</li><li>boolean isAfter(ChronoLocalDate other)：检查此日期是否在指定日期之后。</li><li>boolean isBefore(ChronoLocalDate other)：检查此日期是否早于指定日期。</li><li>boolean isEqual(ChronoLocalDate other)：检查此日期是否等于指定日期</li></ol><blockquote><p>LocalTime、LocalDateTime的用法和LocalDate基本类似</p></blockquote><h2 id="simpledateformat" tabindex="-1"><a class="header-anchor" href="#simpledateformat" aria-hidden="true">#</a> SimpleDateFormat</h2><p>SimpleDateFormat是以locale敏感的方式格式化和解析日期的具体类，用于格式化日期。它允许格式化（日期→文本）、解析（文本→日期）和规范化</p><p>创建sdf对象，SimpleDateFormat sdf = new SimpleDateFormat(&quot;yyyy-MM-dd HH:mm:ss&quot;);</p><ol><li>StringBuffer format(Date date, StringBuffer toAppendTo, FieldPosition pos)：将给定的Date格式化为日期/时间字符串并将结果附加到给定的StringBuffer</li><li>String format(Date date)：将给定的Date格式化为日期/时间字符串</li><li>Date parse(String text, ParsePosition pos)：从字符串解析文本以生成一个Date</li></ol><h2 id="datetimeformatter" tabindex="-1"><a class="header-anchor" href="#datetimeformatter" aria-hidden="true">#</a> DateTimeFormatter</h2><ol><li>static DateTimeFormatter ofPattern(String pattern)：使用指定的模式创建格式化程序</li><li>String format(TemporalAccessor temporal)：使用此格式化程序格式化日期时间对象</li><li>TemporalAccessor parse(CharSequence text)：完全解析文本，生成一个时间对象</li></ol>',39),n=[o];function r(d,c){return a(),l("div",null,n)}const h=e(i,[["render",r],["__file","date.html.vue"]]);export{h as default};
